__global__ void divergent_branch(const float* __restrict__ in, float* __restrict__ out, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        float v = in[i];
        if ((i & 1) == 0) out[i] = v * 2.0f + 1.0f;
        else out[i] = v * 0.5f - 1.0f;
    }
}

